def gen(rng):
    def reduce(s):
        st = []
        for ch in s:
            if ch == '#':
                if st:
                    st.pop()
            else:
                st.append(ch)
        return ''.join(st)

    def embed(r, kmax):
        out = []
        for _ in range(rng.randint(0, 2)):
            out.append('#')
        for c in r:
            k = rng.randint(0, kmax)
            out.append(''.join(rng.choice('abcxyz') for _ in range(k)) + '#' * k)
            out.append(c)
        k = rng.randint(0, kmax)
        out.append(''.join(rng.choice('abcxyz') for _ in range(k)) + '#' * k)
        return ''.join(out)

    tests = ["a\na", "#\na", "#\n#", "a#\n#", "a\nb", "ab\nba", "a#b\nb", "aaa\naaa#", "ab##\nc#d#", "a##c\n#a#c", "abc###\nd#", "ab#\nab"]
    for _ in range(40):
        n = rng.randint(1, 10)
        s = ''.join(rng.choice('ab#') for _ in range(n))
        m = rng.randint(1, 10)
        t = ''.join(rng.choice('ab#') for _ in range(m))
        tests.append(s + "\n" + t)
    for _ in range(25):
        r = ''.join(rng.choice('ab') for _ in range(rng.randint(0, 4)))
        s = embed(r, 3)
        r2 = list(r)
        if r2 and rng.random() < 0.5:
            p = rng.randrange(len(r2))
            r2[p] = 'a' if r2[p] == 'b' else 'b'
        t = embed(''.join(r2), 3)
        if len(s) <= 150 and len(t) <= 150:
            tests.append(s + "\n" + t)
    L = 200000
    while True:
        r = ''.join(rng.choice('abcdefghij') for _ in range(10000))
        s, t = embed(r, 17), embed(r, 17)
        if len(s) <= L and len(t) <= L:
            break
    tests.append(s + "\n" + t)
    r2 = list(r)
    r2[len(r2) - 1] = 'z'
    tests.append(s + "\n" + embed(''.join(r2), 17))
    tests.append('a' * 100000 + '#' * 100000 + "\n" + '#' * 200000)
    tests.append('a' * 100000 + '#' * 99999 + "\n" + 'a' * 199999 + '#')
    tests.append(''.join(rng.choice('ab#') for _ in range(L)) + "\n" + ''.join(rng.choice('ab#') for _ in range(L)))
    tests.append(''.join(rng.choice('a#') for _ in range(L)) + "\n" + ''.join(rng.choice('a#') for _ in range(L)))
    return [x for x in tests if all(x.split('\n'))]
